#!/usr/bin/env python3
"""Convert Create vault inventories and filters in a closed 1.20.1 region directory."""

import argparse
import os
from pathlib import Path
import shutil
import subprocess
import tempfile


def java_classpath(libraries):
    # Use the Mojang-mapped server generated by the NeoForge installer and its
    # Minecraft libraries. The Forge loader and mod classes are not needed.
    roots = (
        "com/mojang", "com/google", "commons-io", "commons-logging", "io/netty", "it/unimi",
        "org/apache/commons", "org/apache/logging/log4j", "org/joml", "org/lz4", "org/slf4j",
    )
    game, = libraries.glob("net/minecraft/server/1.21.1-*/server-1.21.1-*-srg.jar")
    selected = {game}
    for root in roots:
        newest = {}
        for jar in sorted((libraries / root).rglob("*.jar")):
            artifact, version = jar.parent.parent, jar.parent.name
            rank = tuple(int(part) for part in version.split("-")[0].split(".") if part.isdecimal())
            if artifact not in newest or rank > newest[artifact][0]:
                newest[artifact] = (rank, jar)
        selected.update(jar for _, jar in newest.values())
    return os.pathsep.join(map(str, sorted(selected)))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--java-home", required=True, type=Path)
    parser.add_argument("--libraries", required=True, type=Path)
    parser.add_argument("--source-regions", required=True, type=Path)
    parser.add_argument("--target-registry", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    source, output = args.source_regions.resolve(), args.output.resolve()
    if not source.is_dir() or output.exists() or source in output.parents:
        parser.error("Use an existing source and a new output directory outside the source")
    output.parent.mkdir(parents=True, exist_ok=True)
    classpath = java_classpath(args.libraries.resolve())
    sources = Path(__file__).resolve().parent
    java_home = args.java_home.resolve()
    with tempfile.TemporaryDirectory(prefix="expedition-vault-build-") as build:
        subprocess.run([java_home / "bin/javac", "--release", "21", "-proc:none", "-cp", classpath,
                        "-d", build, sources / "VaultMigration.java", sources / "LegacyCreateFilters.java"], check=True)
        # The region collection and recovery file become visible together.
        staging = Path(tempfile.mkdtemp(prefix="expedition-vault-copy-", dir=output.parent))
        try:
            subprocess.run([java_home / "bin/java", "-Xmx2G", "-cp", os.pathsep.join((build, classpath)),
                            "expedition.migration.VaultMigration", source, args.target_registry.resolve(), staging],
                           cwd=build, check=True)
            if output.exists():
                raise FileExistsError(output)
            staging.rename(output)
        finally:
            if staging.exists():
                shutil.rmtree(staging)


if __name__ == "__main__":
    main()
